import{_ as t,c as r,o as e,ah as n}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"高島易断","description":"高島易断，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"高島易断","description":"高島易断，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"ja/articles/takashima/index.md","filePath":"ja/articles/takashima/index.md"}'),s={name:"ja/articles/takashima/index.md"};function o(i,a,l,p,d,c){return e(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="高島易断" tabindex="-1">高島易断 <a class="header-anchor" href="#高島易断" aria-label="Permalink to “高島易断”">​</a></h1><p><strong>『高島易断』</strong>は、明治期の易占家として知られる<strong>高島吞象（1832–1914）</strong>の著作です。通称を「吞象」とし、本名は<strong>高島嘉右衛門</strong>として伝えられています。</p><h2 id="高島と『易-周易-』-物語の流れ" tabindex="-1">高島と『易（周易）』：物語の流れ <a class="header-anchor" href="#高島と『易-周易-』-物語の流れ" aria-label="Permalink to “高島と『易（周易）』：物語の流れ”">​</a></h2><p>『周易』は古代中国において形成され、八卦・六十四卦・卦爻辞、そして後世の注釈（十翼）を通じて体系化されました。哲学的な古典であると同時に、占いとしても用いられてきた書物です。</p><p>高島吞象の伝記には、劇的な転機として「<strong>獄中で易を学んだ</strong>」という逸話が語られます。投獄中に『易経』を手にし、時間のすべてを注いで読み込み、紙捻を筮草に見立てて囚人たちのために占った――苦境のただ中で、卦は机上の古典から「状況を読む言葉」へ変わっていった、というのです。</p><p>とりわけ有名なのが、越獄騒動の折に占ったとされる「<strong>履之井（りのせい）</strong>」の話です。履は虎の尾を踏むような危うさ、井は綱の上り下りという一筋の活路。混乱の中で、物干し縄のような綱を頼りに身を隠して生き延びた――その綱こそが「井」の象だった、という語りは、易の象が現実の動きと重なる瞬間を印象深く描きます。</p><p>出獄後は横浜へ移り、実業と易占の双方で活躍したとされます。人々の相談から時局まで、<strong>卦象・卦辞・爻辞</strong>にもとづく判断を具体の行動へ落とし込み、多くの占例として残したものが『高島易断』です。</p><h2 id="本アプリの収録内容-卦ごと" tabindex="-1">本アプリの収録内容（卦ごと） <a class="header-anchor" href="#本アプリの収録内容-卦ごと" aria-label="Permalink to “本アプリの収録内容（卦ごと）”">​</a></h2><ul><li><strong>卦名解読</strong>：卦名と構造の導入</li><li><strong>卦辞／象辞</strong>：本文の要点</li><li><strong>占断</strong>：高島易断に由来する要点の見立て</li><li><strong>爻変詳解</strong>：各爻の変化解釈と占例</li></ul><p>学習・参照用として掲載しています。原典はパブリックドメインです。</p>',10)])])}const _=t(s,[["render",o]]);export{h as __pageData,_ as default};
